PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE categories (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  name       TEXT NOT NULL UNIQUE,
  slug       TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE posts (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  title           TEXT NOT NULL,
  slug            TEXT NOT NULL UNIQUE,
  category_id     INTEGER NOT NULL REFERENCES categories(id),
  featured_image  TEXT NOT NULL,
  excerpt         TEXT NOT NULL,
  content         TEXT NOT NULL DEFAULT '',
  author          TEXT NOT NULL DEFAULT 'Taqwa Automobile Team',
  tags            TEXT NOT NULL DEFAULT '',      -- comma-separated, simple on purpose
  status          TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published')),
  publish_date    TEXT NOT NULL,                  -- YYYY-MM-DD
  seo_title       TEXT NOT NULL DEFAULT '',
  seo_description TEXT NOT NULL DEFAULT '',
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at      TEXT NOT NULL DEFAULT (datetime('now'))
, language TEXT NOT NULL DEFAULT 'en');
DELETE FROM sqlite_sequence;
CREATE INDEX idx_posts_status_date ON posts(status, publish_date DESC);
CREATE INDEX idx_posts_category ON posts(category_id);
CREATE INDEX idx_posts_language ON posts(language, status, publish_date DESC);
